// Hot100 #1 两数之和（简单）· 数组/哈希
import java.util.*;

class Solution {
    public int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            int need = target - nums[i];
            if (map.containsKey(need)) return new int[] { map.get(need), i };
            map.put(nums[i], i);
        }
        return new int[0];
    }
}

// Hot100 #2 两数相加（中等）· 链表
class Solution {
    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {
        // ① 算法核心思路：从最低位起逐位相加并记录进位，结果按位生成新节点
        // ② 关键步骤与易错点：循环条件 l1 != null || l2 != null || carry != 0 处理不等长与最高位进位
        // ③ 时间复杂度 O(max(n1, n2))，空间复杂度 O(max(n1, n2))（结果链）
        ListNode dummy = new ListNode(0);
        ListNode cur = dummy;
        int carry = 0;
        while (l1 != null || l2 != null || carry != 0) {
            int s = carry;
            if (l1 != null) { s += l1.val; l1 = l1.next; }
            if (l2 != null) { s += l2.val; l2 = l2.next; }
            cur.next = new ListNode(s % 10);
            cur = cur.next;
            carry = s / 10;
        }
        return dummy.next;
    }
}

// Hot100 #3 无重复字符的最长子串（中等）· 滑动窗口
import java.util.*;

class Solution {
    public int lengthOfLongestSubstring(String s) {
        // 核心思路：滑动窗口，右指针扩展、左指针收缩
        // last 记录字符最近一次出现的位置，重复时更新左边界
        // l 只增不减，保证窗口内始终无重复字符
        // 时间复杂度 O(n)，空间复杂度 O(字符集大小)
        Map<Character, Integer> last = new HashMap<>();
        int l = 0, ans = 0;
        for (int r = 0; r < s.length(); r++) {
            char c = s.charAt(r);
            if (last.containsKey(c)) l = Math.max(l, last.get(c) + 1);
            last.put(c, r);
            ans = Math.max(ans, r - l + 1);
        }
        return ans;
    }
}

// Hot100 #4 寻找两个正序数组的中位数（困难）· 二分
class Solution {
    // 核心思路：对较短的数组二分切分点 i，使左半元素数为 (m+n+1)/2，
    // 并保证左半最大值不超过右半最小值，即可直接得到中位数。
    // 易错点：i 或 j 越界时要单独取另一数组的元素，避免访问越界。
    // 时间复杂度 O(log min(m,n))，空间复杂度 O(1)。
    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        int[] A = nums1, B = nums2;
        if (A.length > B.length) { int[] t = A; A = B; B = t; }
        int m = A.length, n = B.length;
        int lo = 0, hi = m;
        int totalLeft = (m + n + 1) / 2;
        while (lo <= hi) {
            int i = (lo + hi) / 2;
            int j = totalLeft - i;
            if (i < m && A[i] < B[j - 1]) {
                lo = i + 1;
            } else if (i > 0 && A[i - 1] > B[j]) {
                hi = i - 1;
            } else {
                int maxLeft;
                if (i == 0) maxLeft = B[j - 1];
                else if (j == 0) maxLeft = A[i - 1];
                else maxLeft = Math.max(A[i - 1], B[j - 1]);
                if ((m + n) % 2 == 1) return (double) maxLeft;
                int minRight;
                if (i == m) minRight = B[j];
                else if (j == n) minRight = A[i];
                else minRight = Math.min(A[i], B[j]);
                return (maxLeft + minRight) / 2.0;
            }
        }
        return 0.0;
    }
}

// Hot100 #5 最长回文子串（中等）· 动态规划/字符串
class Solution {
    // 算法思路：中心扩展法，以每个位置为回文中心向两侧扩散
    // 奇数长度回文中心为单个字符，偶数长度回文中心为相邻两个字符
    // 易错点：扩展停止后 l、r 越界，回文长度为 r-l-1，起点为 l+1
    // 时间复杂度 O(n^2)，空间复杂度 O(1)
    public String longestPalindrome(String s) {
        int n = s.length();
        String best = "";
        for (int i = 0; i < n; i++) {
            int l = i, r = i;  // 奇数长度回文中心
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) { l--; r++; }
            if (r - l - 1 > best.length()) best = s.substring(l + 1, r);
            l = i; r = i + 1;  // 偶数长度回文中心
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) { l--; r++; }
            if (r - l - 1 > best.length()) best = s.substring(l + 1, r);
        }
        return best;
    }
}

// Hot100 #11 盛最多水的容器（中等）· 双指针
class Solution {
    public int maxArea(int[] height) {
        // 核心思路：左右指针从两端相向移动
        // 面积等于较短边乘以宽度，移动较短边才有机会变大
        // 用 long 计算面积防止宽度乘高度溢出
        // 时间复杂度 O(n)，空间复杂度 O(1)
        int l = 0, r = height.length - 1;
        long ans = 0;
        while (l < r) {
            ans = Math.max(ans, (long) Math.min(height[l], height[r]) * (r - l));
            if (height[l] < height[r]) l++;
            else r--;
        }
        return (int) ans;
    }
}

// Hot100 #15 三数之和（中等）· 双指针/排序
import java.util.*;

class Solution {
    public List<List<Integer>> threeSum(int[] nums) {
        // 核心思路：排序后固定第一个数，双指针在剩余区间查找
        // 跳过重复元素避免产生相同三元组
        // 用 long 计算三数之和防止溢出
        // 时间复杂度 O(n^2)，空间复杂度 O(1)（不计结果）
        Arrays.sort(nums);
        int n = nums.length;
        List<List<Integer>> res = new ArrayList<>();
        for (int i = 0; i < n - 2; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;
            int l = i + 1, r = n - 1;
            while (l < r) {
                long s = (long) nums[i] + nums[l] + nums[r];
                if (s < 0) l++;
                else if (s > 0) r--;
                else {
                    res.add(Arrays.asList(nums[i], nums[l], nums[r]));
                    while (l < r && nums[l] == nums[l + 1]) l++;
                    while (l < r && nums[r] == nums[r - 1]) r--;
                    l++; r--;
                }
            }
        }
        return res;
    }
}

// Hot100 #17 电话号码的字母组合（中等）· 回溯
import java.util.*;

class Solution {
    public List<String> letterCombinations(String digits) {
        // 核心思路: 回溯枚举，每个数字从按键字母表选一个字符，拼接出所有组合。
        // 关键步骤: i 表示当前位，path 记录已选字母，递归后恢复现场。
        // 易错点: 空输入直接返回空列表，字符映射需覆盖数字 2 到 9。
        // 复杂度: 时间 O(4^n·n)，空间 O(n) 递归栈。
        List<String> res = new ArrayList<>();
        if (digits.length() == 0) return res;
        String[] map = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
        char[] path = new char[digits.length()];
        dfs(digits, map, 0, path, res);
        return res;
    }
    void dfs(String digits, String[] map, int i, char[] path, List<String> res) {
        if (i == digits.length()) { res.add(new String(path)); return; }
        for (char ch : map[digits.charAt(i) - '0'].toCharArray()) {  // 按按键字母表顺序，保证确定性输出
            path[i] = ch;
            dfs(digits, map, i + 1, path, res);
        }
    }
}

// Hot100 #19 删除链表的倒数第 N 个结点（中等）· 链表/双指针
class Solution {
    public ListNode removeNthFromEnd(ListNode head, int n) {
        // ① 算法核心思路：快指针先走 n 步，再与慢指针同步前进，慢指针落在待删节点前驱
        // ② 关键步骤与易错点：哑节点统一处理删除头节点；循环条件为 fast.next 非空
        // ③ 时间复杂度 O(n)，空间复杂度 O(1)
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode fast = dummy;
        ListNode slow = dummy;
        for (int i = 0; i < n; i++) fast = fast.next;
        while (fast.next != null) {
            fast = fast.next;
            slow = slow.next;
        }
        slow.next = slow.next.next;
        return dummy.next;
    }
}

// Hot100 #20 有效的括号（简单）· 栈
import java.util.*;

class Solution {
    // 核心思路：栈加映射表做括号匹配，右括号与栈顶左括号匹配则弹出。
    // 易错点：栈空遇右括号直接返回 false，最后要求栈为空。
    // 时间复杂度 O(n)，空间复杂度 O(n)。
    public boolean isValid(String s) {
        Deque<Character> st = new ArrayDeque<>();
        Map<Character, Character> pairs = new HashMap<>();
        pairs.put(')', '('); pairs.put(']', '['); pairs.put('}', '{');
        for (char ch : s.toCharArray()) {
            if (pairs.containsKey(ch)) {
                if (st.isEmpty() || st.pop() != pairs.get(ch)) return false;
            } else st.push(ch);
        }
        return st.isEmpty();
    }
}

// Hot100 #21 合并两个有序链表（简单）· 链表
class Solution {
    public ListNode mergeTwoLists(ListNode list1, ListNode list2) {
        // ① 算法核心思路：哑节点加尾指针归并，每轮接入较小节点
        // ② 关键步骤与易错点：比较用 <= 保持稳定性；结束时接入剩余整段链表
        // ③ 时间复杂度 O(n1 + n2)，空间复杂度 O(1)
        ListNode dummy = new ListNode(0);
        ListNode cur = dummy;
        while (list1 != null && list2 != null) {
            if (list1.val <= list2.val) {
                cur.next = list1;
                list1 = list1.next;
            } else {
                cur.next = list2;
                list2 = list2.next;
            }
            cur = cur.next;
        }
        cur.next = list1 != null ? list1 : list2;
        return dummy.next;
    }
}

// Hot100 #22 括号生成（中等）· 回溯
import java.util.*;

class Solution {
    public List<String> generateParenthesis(int n) {
        // 核心思路: 回溯生成合法括号串，任何前缀的右括号数都不超过左括号数。
        // 关键步骤: openCnt 与 closeCnt 统计已放括号数，长度到 2n 时收束。
        // 易错点: 只有 closeCnt 小于 openCnt 时才允许放右括号，保证合法性。
        // 复杂度: 结果数为卡特兰数，时间 O(4^n / sqrt(n))，空间 O(n)。
        List<String> res = new ArrayList<>();
        char[] path = new char[2 * n];
        dfs(0, 0, 0, path, res);
        return res;
    }
    void dfs(int openCnt, int closeCnt, int len, char[] path, List<String> res) {
        int n = path.length / 2;
        if (len == path.length) { res.add(new String(path)); return; }
        if (openCnt < n) {  // 先放左括号，保证确定性顺序
            path[len] = '(';
            dfs(openCnt + 1, closeCnt, len + 1, path, res);
        }
        if (closeCnt < openCnt) {
            path[len] = ')';
            dfs(openCnt, closeCnt + 1, len + 1, path, res);
        }
    }
}

// Hot100 #23 合并 K 个升序链表（困难）· 链表/堆
import java.util.*;

class Solution {
    // 思路：最小堆维护每个链表的当前头节点，每次弹出最小节点接到结果链尾部。
    // 关键点：堆中存节点即可，按 val 比较；空链表不入堆。
    // 易错点：弹出后若该链还有下一节点，继续把下一节点入堆。
    // 复杂度：时间 O(N log k)，N 为节点总数、k 为链表数；空间 O(k)。
    public ListNode mergeKLists(ListNode[] lists) {
        // 小顶堆：堆顶始终是所有链表头中的最小节点
        PriorityQueue<ListNode> pq = new PriorityQueue<>((a, b) -> a.val - b.val);
        for (ListNode h : lists) {
            if (h != null) pq.offer(h);
        }
        ListNode dummy = new ListNode(0);
        ListNode cur = dummy;
        while (!pq.isEmpty()) {
            ListNode node = pq.poll();
            cur.next = node;
            cur = cur.next;
            if (node.next != null) pq.offer(node.next);
        }
        return dummy.next;
    }
}

// Hot100 #24 两两交换链表中的节点（中等）· 链表
class Solution {
    public ListNode swapPairs(ListNode head) {
        // ① 算法核心思路：哑节点加三指针，每轮交换相邻两个节点后前移一对
        // ② 关键步骤与易错点：按 a.next = b.next、b.next = a、prev.next = b 的顺序调整指针
        // ③ 时间复杂度 O(n)，空间复杂度 O(1)
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode prev = dummy;
        while (prev.next != null && prev.next.next != null) {
            ListNode a = prev.next;
            ListNode b = a.next;
            a.next = b.next;
            b.next = a;
            prev.next = b;
            prev = a;
        }
        return dummy.next;
    }
}

// Hot100 #25 K 个一组翻转链表（困难）· 链表
class Solution {
    // 反转区间 [a, b)，返回新头
    private ListNode reverse(ListNode a, ListNode b) {
        ListNode pre = null;
        while (a != b) {
            ListNode nxt = a.next;
            a.next = pre;
            pre = a;
            a = nxt;
        }
        return pre;
    }

    // 思路：按 k 个节点为一组，借助哑结点和区间反转 [a, b) 实现整组翻转后重新拼接。
    // 关键点：先检查剩余节点是否满 k 个，不足则保持原序直接返回。
    // 易错点：反转后要用 first 接上下一段的头 nxt，并让 pre 前进到 first 作为下一组前驱。
    // 复杂度：时间 O(n)，空间 O(1)。
    public ListNode reverseKGroup(ListNode head, int k) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode pre = dummy;
        while (true) {
            ListNode tail = pre;
            for (int i = 0; i < k; i++) {
                tail = tail.next;
                if (tail == null) return dummy.next;  // 剩余不足 k 个，保持原序
            }
            ListNode nxt = tail.next;
            ListNode first = pre.next;
            pre.next = reverse(first, tail.next);
            first.next = nxt;
            pre = first;
        }
    }
}

// Hot100 #31 下一个排列（中等）· 数组
class Solution {
    // 算法思路：从右向左找第一个 nums[i] < nums[i+1] 的下降点 i
    // 再从右向左找第一个大于 nums[i] 的数与之交换，最后反转 i 之后区间使其升序
    // 易错点：整个序列为降序时 i 为 -1，此时直接反转整个数组
    // 时间复杂度 O(n)，空间复杂度 O(1)
    public void nextPermutation(int[] nums) {
        int n = nums.length;
        int i = n - 2;
        while (i >= 0 && nums[i] >= nums[i + 1]) i--;
        if (i >= 0) {
            int j = n - 1;
            while (j > i && nums[j] <= nums[i]) j--;
            swap(nums, i, j);
        }
        reverse(nums, i + 1, n - 1);  // 反转后缀得到下一个排列
    }

    private void swap(int[] a, int x, int y) {
        int t = a[x]; a[x] = a[y]; a[y] = t;
    }

    private void reverse(int[] a, int l, int r) {
        while (l < r) {
            int t = a[l]; a[l] = a[r]; a[r] = t;
            l++; r--;
        }
    }
}

// Hot100 #32 最长有效括号（困难）· 动态规划/栈

class Solution {
    public int longestValidParentheses(String s) {
        // 算法思路：动态规划。dp[i] 表示以 s[i] 结尾的最长有效括号子串长度，
        // 仅当 s[i] 为右括号时更新，分直接配对与跨段配对两种情况。
        // 关键点：跨段配对时要加上左括号之前的 dp 值，注意下标越界判断。
        // 时间复杂度 O(n)，空间复杂度 O(n)。
        int n = s.length();
        int[] dp = new int[n];
        int res = 0;
        for (int i = 1; i < n; i++) {
            if (s.charAt(i) == ')') {
                if (s.charAt(i - 1) == '(') {
                    dp[i] = (i >= 2 ? dp[i - 2] : 0) + 2;
                } else if (i - dp[i - 1] - 1 >= 0 && s.charAt(i - dp[i - 1] - 1) == '(') {
                    dp[i] = dp[i - 1] + 2 + (i - dp[i - 1] - 2 >= 0 ? dp[i - dp[i - 1] - 2] : 0);
                }
                res = Math.max(res, dp[i]);
            }
        }
        return res;
    }
}

// Hot100 #33 搜索旋转排序数组（中等）· 二分
class Solution {
    // 核心思路：旋转数组二分，每次循环至少有一半是有序的，
    // 先判断 target 是否落在有序半边再决定向哪边收缩。
    // 易错点：左半有序的判断条件是 nums[lo] <= nums[mid]。
    // 时间复杂度 O(log n)，空间复杂度 O(1)。
    public int search(int[] nums, int target) {
        int lo = 0, hi = nums.length - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] == target) return mid;
            if (nums[lo] <= nums[mid]) { // 左半有序
                if (nums[lo] <= target && target < nums[mid]) hi = mid - 1;
                else lo = mid + 1;
            } else { // 右半有序
                if (nums[mid] < target && target <= nums[hi]) lo = mid + 1;
                else hi = mid - 1;
            }
        }
        return -1;
    }
}

// Hot100 #34 在排序数组中查找元素的第一个和最后一个位置（中等）· 二分
class Solution {
    // 核心思路：两次二分，lower 求第一个 >= target 的下标，
    // upper 求第一个 > target 的下标，答案即 [lower, upper-1]。
    // 易错点：lower 越界或指向元素不等于 target 时返回 [-1, -1]。
    // 时间复杂度 O(log n)，空间复杂度 O(1)。
    public int[] searchRange(int[] nums, int target) {
        int l = lowerBound(nums, target);
        if (l == nums.length || nums[l] != target) return new int[] {-1, -1};
        int r = upperBound(nums, target) - 1;
        return new int[] {l, r};
    }

    // 第一个 >= target 的位置
    int lowerBound(int[] nums, int target) {
        int lo = 0, hi = nums.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    // 第一个 > target 的位置
    int upperBound(int[] nums, int target) {
        int lo = 0, hi = nums.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

// Hot100 #35 搜索插入位置（简单）· 二分
class Solution {
    // 核心思路：二分查找第一个 >= target 的位置即插入下标。
    // 易错点：hi 初始为 nums.length，左闭右开写法，循环条件 lo < hi。
    // 时间复杂度 O(log n)，空间复杂度 O(1)。
    public int searchInsert(int[] nums, int target) {
        int lo = 0, hi = nums.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

// Hot100 #39 组合总和（中等）· 回溯
import java.util.*;

class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        // 核心思路: 回溯加剪枝，每个数可以重复选取，用 start 限制下标只增不减。
        // 关键步骤: remain 减到 0 时记录答案，候选值大于 remain 时跳过该分支。
        // 易错点: 递归时仍传当前下标 i，才能让同一个数字被重复使用。
        // 复杂度: 最坏指数级时间，空间 O(target / min) 递归深度。
        List<List<Integer>> res = new ArrayList<>();
        int[] path = new int[target];
        dfs(candidates, target, 0, path, 0, res);
        return res;
    }
    void dfs(int[] candidates, int remain, int start, int[] path, int len, List<List<Integer>> res) {
        if (remain == 0) {
            List<Integer> one = new ArrayList<>();
            for (int i = 0; i < len; i++) one.add(path[i]);
            res.add(one);
            return;
        }
        for (int i = start; i < candidates.length; i++) {  // 下标只增不减，避免重复组合
            if (candidates[i] > remain) continue;
            path[len] = candidates[i];
            dfs(candidates, remain - candidates[i], i, path, len + 1, res);
        }
    }
}

// Hot100 #41 缺失的第一个正数（困难）· 数组/原地哈希
class Solution {
    public int firstMissingPositive(int[] nums) {
        // 核心思路：原地哈希，把值 x（1<=x<=n）放到下标 x-1 处，
        // 使 nums[i] == i+1，缺失的最小正整数即可按下标判断。
        // 关键步骤：while 反复交换直到目标就位或越界；最后找第一个
        // nums[i] != i+1 的位置，若全部就位则答案是 n+1。
        // 复杂度：时间 O(n)，空间 O(1)。
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            while (nums[i] >= 1 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {
                int idx = nums[i] - 1;
                int t = nums[i]; nums[i] = nums[idx]; nums[idx] = t;
            }
        }
        for (int i = 0; i < n; i++) {
            if (nums[i] != i + 1) return i + 1;
        }
        return n + 1;
    }
}

// Hot100 #42 接雨水（困难）· 双指针/栈
class Solution {
    public int trap(int[] height) {
        // 核心思路：某位置存水量取决于左右最高柱的较小者
        // 双指针从两端向中间推进，同时维护两侧最大值
        // 结算较矮一侧的水量，避免额外的前后缀数组
        // 时间复杂度 O(n)，空间复杂度 O(1)
        int n = height.length;
        int l = 0, r = n - 1, lmax = 0, rmax = 0;
        long ans = 0;
        while (l <= r) {
            if (lmax <= rmax) {
                lmax = Math.max(lmax, height[l]);
                ans += lmax - height[l];
                l++;
            } else {
                rmax = Math.max(rmax, height[r]);
                ans += rmax - height[r];
                r--;
            }
        }
        return (int) ans;
    }
}

// Hot100 #45 跳跃游戏 II（中等）· 贪心
class Solution {
    // 算法思路: 贪心。curEnd 是当前这一跳的边界, farthest 记录遍历中可达的最远下标。
    // 关键点: 只遍历到倒数第二格; 到达 curEnd 时跳数加一, 并将边界更新为 farthest。
    // 时间复杂度 O(n), 空间复杂度 O(1)。
    public int jump(int[] nums) {
        int n = nums.length;
        if (n <= 1) return 0;
        int jumps = 0, curEnd = 0, farthest = 0;
        for (int i = 0; i < n - 1; i++) {
            farthest = Math.max(farthest, i + nums[i]);
            if (i == curEnd) {
                jumps++;
                curEnd = farthest;
            }
        }
        return jumps;
    }
}

// Hot100 #46 全排列（中等）· 回溯
import java.util.*;

class Solution {
    public List<List<Integer>> permute(int[] nums) {
        // 核心思路: 回溯生成全排列，用 used 数组标记哪些下标已被选取。
        // 关键步骤: 每层按下标递增顺序尝试未用元素，递归返回后撤销选择。
        // 易错点: 撤销时必须同时弹出 path 并复位 used，保证现场完全还原。
        // 复杂度: 时间 O(n·n!)，空间 O(n) 递归栈。
        int n = nums.length;
        boolean[] used = new boolean[n];
        List<List<Integer>> res = new ArrayList<>();
        int[] path = new int[n];
        dfs(nums, used, path, 0, res);
        return res;
    }
    void dfs(int[] nums, boolean[] used, int[] path, int depth, List<List<Integer>> res) {
        int n = nums.length;
        if (depth == n) {
            List<Integer> one = new ArrayList<>();
            for (int x : path) one.add(x);
            res.add(one);
            return;
        }
        for (int i = 0; i < n; i++) {  // 按下标递增顺序尝试，保证确定性输出
            if (used[i]) continue;
            used[i] = true;
            path[depth] = nums[i];
            dfs(nums, used, path, depth + 1, res);
            used[i] = false;
        }
    }
}

// Hot100 #48 旋转图像（中等）· 矩阵
class Solution {
    public void rotate(int[][] matrix) {
        // 核心思路：先沿主对角线转置，再逐行反转，两步合成顺时针旋转 90 度。
        // 关键步骤：转置时内层循环从 i+1 开始，避免对角元素被重复交换；
        // 反转必须对每一行整体进行，两步顺序不能颠倒。
        // 复杂度：时间 O(n^2)，空间 O(1)。
        int n = matrix.length;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++) { int t = matrix[i][j]; matrix[i][j] = matrix[j][i]; matrix[j][i] = t; }
        for (int i = 0; i < n; i++)
            for (int l = 0, r = n - 1; l < r; l++, r--) { int t = matrix[i][l]; matrix[i][l] = matrix[i][r]; matrix[i][r] = t; }
    }
}

// Hot100 #49 字母异位词分组（中等）· 哈希/字符串
import java.util.*;

class Solution {
    public List<List<String>> groupAnagrams(String[] strs) {
        // 核心思路：把每个字符串排序得到统一键，哈希表按键分组
        // 键首次出现时新建分组并记录组下标
        // 时间复杂度 O(n * k log k)，空间复杂度 O(n * k)
        Map<String, Integer> idx = new HashMap<>();
        List<List<String>> groups = new ArrayList<>();
        for (String s : strs) {
            char[] ca = s.toCharArray();
            Arrays.sort(ca);
            String key = new String(ca);
            if (!idx.containsKey(key)) {
                idx.put(key, groups.size());
                groups.add(new ArrayList<String>());
            }
            groups.get(idx.get(key)).add(s);
        }
        return groups;
    }
}

// Hot100 #51 N 皇后（困难）· 回溯
import java.util.*;

class Solution {
    // 核心思路：回溯逐行放置皇后，用列、两条对角线的占用标记剪枝。
    // 关键点：d1[r+c] 与 d2[r-c+n-1] 分别对应两条对角线方向。
    // 易错点：递归返回后需撤销标记并还原棋盘。
    // 时间复杂度 O(n!)，空间复杂度 O(n)。
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> res = new ArrayList<>();
        char[][] board = new char[n][n];
        for (char[] row : board) Arrays.fill(row, '.');
        boolean[] cols = new boolean[n];
        boolean[] d1 = new boolean[2 * n - 1];
        boolean[] d2 = new boolean[2 * n - 1];
        dfs(0, n, board, cols, d1, d2, res);
        return res;
    }

    void dfs(int r, int n, char[][] board, boolean[] cols, boolean[] d1, boolean[] d2, List<List<String>> res) {
        if (r == n) {
            List<String> sol = new ArrayList<>();
            for (int i = 0; i < n; i++) sol.add(new String(board[i]));
            res.add(sol);
            return;
        }
        for (int c = 0; c < n; c++) {
            if (cols[c] || d1[r + c] || d2[r - c + n - 1]) continue;
            cols[c] = d1[r + c] = d2[r - c + n - 1] = true;
            board[r][c] = 'Q';
            dfs(r + 1, n, board, cols, d1, d2, res);
            board[r][c] = '.';
            cols[c] = d1[r + c] = d2[r - c + n - 1] = false;
        }
    }
}

// Hot100 #53 最大子数组和（中等）· 动态规划
class Solution {
    public int maxSubArray(int[] nums) {
        // 核心思路：Kadane 算法，cur 记录以当前位置结尾的最大子数组和，
        // 每个元素要么单独成段，要么接在前一个最优段之后，二者取较大值。
        // 关键步骤：best 持续更新为全局最大值；全为负数时 cur 也能正确
        // 从最大元素重新开始，因此无需特判。
        // 复杂度：时间 O(n)，空间 O(1)。
        int cur = nums[0], best = nums[0];
        for (int i = 1; i < nums.length; i++) {
            cur = Math.max(nums[i], cur + nums[i]);
            best = Math.max(best, cur);
        }
        return best;
    }
}

// Hot100 #54 螺旋矩阵（中等）· 矩阵
import java.util.*;

class Solution {
    public List<Integer> spiralOrder(int[][] matrix) {
        // 核心思路：用边界收缩法按上、右、下、左四条边逐圈读取元素。
        // 关键步骤：每圈走完上、右两边后检查区域是否仍有效再走下面两边，
        // 否则单行或单列场景会重复读取元素。
        // 复杂度：时间 O(mn)，空间 O(1)（不计返回数组）。
        List<Integer> r = new ArrayList<>();
        if (matrix.length == 0) return r;
        int m = matrix.length, n = matrix[0].length;
        int top = 0, bottom = m - 1, left = 0, right = n - 1;
        while (top <= bottom && left <= right) {
            for (int j = left; j <= right; j++) r.add(matrix[top][j]);
            for (int i = top + 1; i <= bottom; i++) r.add(matrix[i][right]);
            if (top < bottom) for (int j = right - 1; j >= left; j--) r.add(matrix[bottom][j]);
            if (left < right) for (int i = bottom - 1; i > top; i--) r.add(matrix[i][left]);
            top++; bottom--; left++; right--;
        }
        return r;
    }
}

// Hot100 #55 跳跃游戏（中等）· 贪心
class Solution {
