// Hot100 #56 合并区间（中等）· 排序/区间
import java.util.*;

class Solution {
    public int[][] merge(int[][] intervals) {
        // 核心思路：先按左端点排序，使可能重叠的区间必然相邻，再线性扫描合并。
        // 关键步骤：当前区间左端点不超过结果末尾区间的右端点时合并，并把右端点
        // 更新为两者较大值；否则作为新区间直接加入结果。
        // 复杂度：时间 O(n log n)（排序主导），空间 O(n)。
        Arrays.sort(intervals, (a, b) -> a[0] - b[0]);
        List<int[]> res = new ArrayList<>();
        for (int[] p : intervals) {
            if (!res.isEmpty() && p[0] <= res.get(res.size() - 1)[1])
                res.get(res.size() - 1)[1] = Math.max(res.get(res.size() - 1)[1], p[1]);
            else
                res.add(p);
        }
        return res.toArray(new int[0][]);
    }
}

// Hot100 #62 不同路径（中等）· 动态规划
class Solution {
    // 算法思路：动态规划，dp[i][j] 表示从左上角走到 (i,j) 的路径总数
    // 转移方程 dp[i][j] = dp[i-1][j] + dp[i][j-1]，从上边或左边一步到达
    // 第一行与第一列各只有一条路径，需先初始化边界
    // 用 long 存储防止中间结果溢出，时间复杂度 O(m*n)，空间复杂度 O(m*n)
    public int uniquePaths(int m, int n) {
        long[][] dp = new long[m][n];
        for (int i = 0; i < m; i++) dp[i][0] = 1;  // 第一列只有一条路径
        for (int j = 0; j < n; j++) dp[0][j] = 1;  // 第一行只有一条路径
        for (int i = 1; i < m; i++)
            for (int j = 1; j < n; j++)
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1];
        return (int) dp[m - 1][n - 1];
    }
}

// Hot100 #64 最小路径和（中等）· 动态规划
class Solution {
    // 算法思路：动态规划，dp[i][j] 表示到达 (i,j) 时的最小路径和
    // 转移方程 dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]
    // 第一行与第一列路径唯一，需先初始化边界
    // 时间复杂度 O(m*n)，空间复杂度 O(m*n)
    public int minPathSum(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] dp = new int[m][n];
        dp[0][0] = grid[0][0];
        for (int j = 1; j < n; j++) dp[0][j] = dp[0][j - 1] + grid[0][j];  // 第一行只能从左累加
        for (int i = 1; i < m; i++) dp[i][0] = dp[i - 1][0] + grid[i][0];  // 第一列只能从上累加
        for (int i = 1; i < m; i++)
            for (int j = 1; j < n; j++)
                dp[i][j] = Math.min(dp[i - 1][j], dp[i][j - 1]) + grid[i][j];
        return dp[m - 1][n - 1];
    }
}

