class Solution {
    public int climbStairs(int n) {
        // 算法思路：斐波那契递推。爬到第 i 阶的方法数等于第 i-1 阶与第 i-2 阶之和，
        // 因为最后一步要么跨 1 级要么跨 2 级。
        // 关键点：用滚动变量 a、b 只保留前两个状态，无需完整 dp 数组。
        // 易错点：n 较大时用 long 计算避免中间值溢出，最后转回 int。
        // 时间复杂度 O(n)，空间复杂度 O(1)。
        if (n <= 2) return n;
        long a = 1, b = 2;
        for (int i = 3; i <= n; i++) {
            long c = a + b;
            a = b;
            b = c;
        }
        return (int) b;
    }
}

// Hot100 #72 编辑距离（中等）· 动态规划
class Solution {
    // 算法思路：动态规划，dp[i][j] 表示 word1 前 i 个字符转换为 word2 前 j 个字符的最少操作数
    // 字符相等则继承 dp[i-1][j-1]，否则取插入、删除、替换的最小值再加一
    // 边界：dp[i][0]=i 表示删除 i 个字符，dp[0][j]=j 表示插入 j 个字符
    // 时间复杂度 O(m*n)，空间复杂度 O(m*n)
    public int minDistance(String word1, String word2) {
        int m = word1.length(), n = word2.length();
        int[][] dp = new int[m + 1][n + 1];
        for (int i = 0; i <= m; i++) dp[i][0] = i;
        for (int j = 0; j <= n; j++) dp[0][j] = j;
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (word1.charAt(i - 1) == word2.charAt(j - 1)) dp[i][j] = dp[i - 1][j - 1];
                else dp[i][j] = Math.min(dp[i - 1][j], Math.min(dp[i][j - 1], dp[i - 1][j - 1])) + 1;
            }
        }
        return dp[m][n];
    }
}

// Hot100 #73 矩阵置零（中等）· 矩阵
class Solution {
    public void setZeroes(int[][] matrix) {
        // 核心思路：用第一行和第一列充当标记数组，实现 O(1) 额外空间。
        // 关键步骤：先单独记录第一行、第一列本身是否含 0；再用第一行第一列的
        // 标记把内部元素置零；最后根据记录单独处理第一行第一列，避免标记被覆盖。
        // 复杂度：时间 O(mn)，空间 O(1)。
        int m = matrix.length, n = matrix[0].length;
        boolean firstRow = false, firstCol = false;
        for (int j = 0; j < n; j++) if (matrix[0][j] == 0) firstRow = true;
        for (int i = 0; i < m; i++) if (matrix[i][0] == 0) firstCol = true;
        for (int i = 1; i < m; i++)
            for (int j = 1; j < n; j++)
                if (matrix[i][j] == 0) { matrix[i][0] = 0; matrix[0][j] = 0; }
        for (int i = 1; i < m; i++)
            for (int j = 1; j < n; j++)
                if (matrix[i][0] == 0 || matrix[0][j] == 0) matrix[i][j] = 0;
        if (firstRow) for (int j = 0; j < n; j++) matrix[0][j] = 0;
        if (firstCol) for (int i = 0; i < m; i++) matrix[i][0] = 0;
    }
}

// Hot100 #74 搜索二维矩阵（中等）· 二分
class Solution {
    // 核心思路：矩阵整体按一维有序数组二分，mid 映射为行列取值。
    // 易错点：mid / n 与 mid % n 完成下标转换。
    // 时间复杂度 O(log(m*n))，空间复杂度 O(1)。
    public boolean searchMatrix(int[][] matrix, int target) {
        int m = matrix.length, n = matrix[0].length;
        int lo = 0, hi = m * n - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            int v = matrix[mid / n][mid % n];
            if (v == target) return true;
            if (v < target) lo = mid + 1;
            else hi = mid - 1;
        }
        return false;
    }
}

// Hot100 #75 颜色分类（中等）· 双指针/排序
class Solution {
    // 算法思路：荷兰国旗问题，用三指针原地对 0、1、2 排序
    // i 指向 0 区域的右边界，k 指向 2 区域的左边界，j 为当前扫描指针
    // 易错点：与 2 交换后 j 不前进，换来的元素还需再次判断
    // 时间复杂度 O(n)，空间复杂度 O(1)
    public void sortColors(int[] nums) {
        int i = 0, j = 0, k = nums.length - 1;
        while (j <= k) {
            if (nums[j] == 0) { swap(nums, i, j); i++; j++; }
            else if (nums[j] == 2) { swap(nums, j, k); k--; }
            else j++;
        }
    }

    private void swap(int[] a, int x, int y) {
        int t = a[x]; a[x] = a[y]; a[y] = t;
    }
}

// Hot100 #76 最小覆盖子串（困难）· 滑动窗口
class Solution {
    public String minWindow(String s, String t) {
        // 核心思路：滑动窗口加计数。need 记录 t 中每个字符的需求次数，
        // formed 统计当前窗口内已满足出现次数的字符种类数。
        // 关键步骤：右指针扩张窗口直至 formed 达标，再收缩左指针寻找更短
        // 覆盖子串并更新最优解；移动左指针时同步回退计数。
        // 复杂度：时间 O(len(s)+len(t))，空间 O(|字符集|)。
        if (t.length() == 0) return "";
        int[] need = new int[128], have = new int[128];
        for (int i = 0; i < t.length(); i++) need[t.charAt(i)]++;
        int formed = 0, required = 0;
        for (int i = 0; i < 128; i++) if (need[i] > 0) required++;
        int left = 0, bestL = -1, bestLen = Integer.MAX_VALUE;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            have[c]++;
            if (need[c] > 0 && have[c] == need[c]) formed++;
            while (formed == required && left <= right) {
                if (right - left + 1 < bestLen) {
                    bestLen = right - left + 1;
                    bestL = left;
                }
                char lc = s.charAt(left);
                have[lc]--;
                if (need[lc] > 0 && have[lc] < need[lc]) formed--;
                left++;
            }
        }
        return bestL == -1 ? "" : s.substring(bestL, bestL + bestLen);
    }
}

