        return res;
    }
    void dfs(int[] nums, int start, int[] path, int len, List<List<Integer>> res) {
        List<Integer> one = new ArrayList<>();
        for (int i = 0; i < len; i++) one.add(path[i]);
        res.add(one);
        for (int i = start; i < nums.length; i++) {  // 按起始下标递增扩展，保证确定性顺序
            path[len] = nums[i];
            dfs(nums, i + 1, path, len + 1, res);
        }
    }
}

// Hot100 #79 单词搜索（中等）· 回溯
class Solution {
    int m, n;
    public boolean exist(char[][] board, String word) {
        // 核心思路: 回溯搜索，从任意格子出发沿四个方向逐字符匹配 word。
        // 关键步骤: 越界或字符不匹配立即返回 false，匹配完最后一个字符即成功。
        // 易错点: 访问过的格子要标记为 #，回溯后必须恢复原字符。
        // 复杂度: 时间 O(m·n·3^k)，空间 O(k) 递归栈，k 为单词长度。
        if (word.length() == 0) return true;
        m = board.length; n = board[0].length;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (dfs(board, word, i, j, 0)) return true;
        return false;
    }
    boolean dfs(char[][] board, String word, int i, int j, int k) {
        if (i < 0 || i >= m || j < 0 || j >= n || board[i][j] != word.charAt(k)) return false;
        if (k == word.length() - 1) return true;
        board[i][j] = '#';  // 标记已访问
        boolean found = dfs(board, word, i + 1, j, k + 1)
                     || dfs(board, word, i - 1, j, k + 1)
                     || dfs(board, word, i, j + 1, k + 1)
                     || dfs(board, word, i, j - 1, k + 1);
        board[i][j] = word.charAt(k);  // 回溯恢复
        return found;
    }
}

// Hot100 #84 柱状图中最大的矩形（困难）· 单调栈
import java.util.*;

class Solution {
    // 算法思路: 单调栈。栈中存下标且高度递增, 遇到更矮的柱子时弹出并计算矩形面积。
    // 关键点: 末尾追加 0 哨兵保证所有柱子出栈; 弹出后新栈顶即左侧边界。
    // 时间复杂度 O(n), 空间复杂度 O(n)。
    public int largestRectangleArea(int[] heights) {
        int n = heights.length;
        int[] h = new int[n + 1];
        System.arraycopy(heights, 0, h, 0, n);
        h[n] = 0;                        // 末尾哨兵
        Deque<Integer> st = new ArrayDeque<>();
        st.push(-1);
        long ans = 0;
        for (int i = 0; i < h.length; i++) {
            while (st.peek() != -1 && h[st.peek()] > h[i]) {
                int idx = st.pop();
                ans = Math.max(ans, (long) h[idx] * (i - st.peek() - 1));
            }
            st.push(i);
        }
        return (int) ans;
    }
}

