    // 关键:左右子树贡献先与 0 取大,再更新全局答案
    // 易错:ans 初始化为 Integer.MIN_VALUE,防止全负节点
    // 复杂度:时间 O(n),空间 O(h),h 为树高
    int ans;

    public int maxPathSum(TreeNode root) {
        ans = Integer.MIN_VALUE;
        dfs(root);
