class Solution {
    // 思路：链表归并排序，快慢指针找中点把链表一分为二，递归排序后合并两条有序链。
    // 关键点：快指针从 head.next 起步，保证偶数长度时 slow 落在左半段末尾。
    // 易错点：拆链前先记录 mid，再把 slow.next 置空截断；合并用哑结点统一处理。
    // 复杂度：时间 O(n log n)，空间 O(log n)（递归栈）。
    public ListNode sortList(ListNode head) {
        if (head == null || head.next == null) return head;
        // 快慢指针找中点，拆成两半
        ListNode slow = head;
        ListNode fast = head.next;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        ListNode mid = slow.next;
        slow.next = null;
        ListNode left = sortList(head);
        ListNode right = sortList(mid);
        // 归并两个有序链表
        ListNode dummy = new ListNode(0);
        ListNode cur = dummy;
        while (left != null && right != null) {
            if (left.val <= right.val) {
                cur.next = left;
                left = left.next;
            } else {
                cur.next = right;
                right = right.next;
            }
            cur = cur.next;
        }
        cur.next = left != null ? left : right;
        return dummy.next;
    }
}

// Hot100 #152 乘积最大子数组（中等）· 动态规划

class Solution {
    public int maxProduct(int[] nums) {
        // 算法思路：动态规划。同时维护以当前元素结尾的最大乘积 cur_max 与
        // 最小乘积 cur_min，负数会反转大小关系，需要两个状态（负负得正）。
        // 关键点：遇到负数先交换两个状态再更新；每个元素可单独成子数组。
        // 易错点：中间乘积可能溢出 int，用 long 计算后转回 int。
        // 时间复杂度 O(n)，空间复杂度 O(1)。
        long cur_max = nums[0], cur_min = nums[0], best = nums[0];
        for (int i = 1; i < nums.length; i++) {
            long v = nums[i];
            if (v < 0) { // 负数反转大小关系
                long t = cur_max;
                cur_max = cur_min;
                cur_min = t;
            }
            cur_max = Math.max(v, cur_max * v);
            cur_min = Math.min(v, cur_min * v);
            best = Math.max(best, cur_max);
        }
        return (int) best;
    }
}

// Hot100 #153 寻找旋转排序数组中的最小值（中等）· 二分
class Solution {
    // 核心思路：与右端点比较二分，nums[mid] > nums[hi] 时最小值在右半边。
    // 易错点：循环条件 lo < hi，结束时 lo 即最小值下标。
    // 时间复杂度 O(log n)，空间复杂度 O(1)。
    public int findMin(int[] nums) {
        int lo = 0, hi = nums.length - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] > nums[hi]) lo = mid + 1;
            else hi = mid;
        }
        return nums[lo];
    }
}

// Hot100 #155 最小栈（中等）· 栈/设计
import java.util.*;

class MinStack {
    // 核心思路：辅助栈 min_st 与主栈同步维护当前最小值。
    // 关键点：push 时仅当 val 不大于 min_st 栈顶才入辅助栈；
    // pop 时若栈顶等于 min_st 栈顶则同步弹出。
    // 易错点：getMin 直接返回 min_st 栈顶。
    // 时间复杂度 O(1)，空间复杂度 O(n)。
    Deque<Integer> st = new ArrayDeque<>();
    Deque<Integer> minSt = new ArrayDeque<>();

    public MinStack() {}

    public void push(int val) {
        st.push(val);
        if (minSt.isEmpty() || val <= minSt.peek()) minSt.push(val);
    }

    public void pop() {
        if (st.isEmpty()) return;
        if (st.peek().equals(minSt.peek())) minSt.pop();
        st.pop();
    }

    public int top() {
        return st.peek();
    }

    public int getMin() {
        return minSt.peek();
    }
}

