class Solution {
    public int rob(int[] nums) {
        // 算法思路：动态规划。rob1 为偷到当前家的最大收益，rob2 为偷到上一家的最大收益，
        // 每家的选择是偷或不偷：max(rob1, rob2 + v)。
        // 关键点：相邻两家不能同时偷，更新顺序要先保存旧 rob1 再滚动。
        // 易错点：用 long 避免累加溢出。
        // 时间复杂度 O(n)，空间复杂度 O(1)。
        long rob2 = 0, rob1 = 0;
        for (int v : nums) {
            long nxt = Math.max(rob1, rob2 + v);
            rob2 = rob1;
            rob1 = nxt;
        }
        return (int) rob1;
    }
}

// Hot100 #199 二叉树的右视图（中等）· 二叉树/BFS
import java.util.*;

class Solution {
    // 思路:BFS 层序遍历,收集每层最后一个节点
    // 关键:记录每层节点数 sz,弹出到最后一个时记录值
    // 易错:空树直接返回空结果
    // 复杂度:时间 O(n),空间 O(n)
    public List<Integer> rightSideView(TreeNode root) {
        List<Integer> out = new ArrayList<>();
        if (root == null) return out;
        Queue<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        while (!q.isEmpty()) {
            int sz = q.size();
            for (int i = 0; i < sz; i++) {
                TreeNode cur = q.poll();
                if (i == sz - 1) out.add(cur.val);  // 本层最后一个节点即右视图节点
                if (cur.left != null) q.add(cur.left);
                if (cur.right != null) q.add(cur.right);
            }
        }
        return out;
    }
}

// Hot100 #200 岛屿数量（中等）· 图/DFS/BFS
class Solution {
    int m, n;
    public int numIslands(char[][] grid) {
        // 核心思路: 遍历网格，遇到陆地就计数并把整座岛屿淹没，避免重复统计。
        // 关键步骤: dfs 沿上下左右扩散，把访问过的陆地改为 0。
        // 易错点: 先判断越界再访问格子，防止下标越界。
        // 复杂度: 每个格子最多访问一次，时间 O(m·n)，空间 O(m·n) 最坏递归栈。
        if (grid.length == 0 || grid[0].length == 0) return 0;
        m = grid.length; n = grid[0].length;
        int cnt = 0;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] == '1') { cnt++; dfs(grid, i, j); }
        return cnt;
    }
    void dfs(char[][] g, int i, int j) {
        if (i < 0 || i >= m || j < 0 || j >= n || g[i][j] != '1') return;
        g[i][j] = '0';
        dfs(g, i + 1, j); dfs(g, i - 1, j); dfs(g, i, j + 1); dfs(g, i, j - 1);
    }
}

// Hot100 #206 反转链表（简单）· 链表
class Solution {
