    public Trie() {}
    public void insert(String word) {
        Trie cur = this;
        for (char c : word.toCharArray()) { int i = c - 'a'; if (cur.next[i] == null) cur.next[i] = new Trie(); cur = cur.next[i]; }
        cur.end = true;
    }
    public boolean search(String word) {
        Trie cur = walk(word);
        return cur != null && cur.end;
    }
    public boolean startsWith(String prefix) {
        return walk(prefix) != null;
    }
    Trie walk(String s) {
        Trie cur = this;
        for (char c : s.toCharArray()) { int i = c - 'a'; if (cur.next[i] == null) return null; cur = cur.next[i]; }
        return cur;
    }
}

// Hot100 #215 数组中的第 K 个最大元素（中等）· 堆/快选
import java.util.*;

class Solution {
    // 算法思路: 小根堆。堆中始终保存最大的 k 个元素, 堆顶即第 k 大。
    // 关键点: 新元素大于堆顶时才弹出并入堆, 保证堆容量恒为 k。
    // 时间复杂度 O(n log k), 空间复杂度 O(k)。
    public int findKthLargest(int[] nums, int k) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();  // 大小为 k 的小根堆
        for (int i = 0; i < k; i++) pq.add(nums[i]);
        for (int i = k; i < nums.length; i++) {
            if (nums[i] > pq.peek()) { pq.poll(); pq.add(nums[i]); }
        }
        return pq.peek();
    }
}

// Hot100 #226 翻转二叉树（简单）· 二叉树
class Solution {
    // 思路：自顶向下递归，先交换当前节点的左右子树，再递归处理左右子树。
    // 易错点：空节点直接返回，交换与递归的顺序不影响结果。
    // 复杂度：时间 O(n)，空间 O(h)，h 为树高（递归栈深度）。
    public TreeNode invertTree(TreeNode root) {
        if (root == null) return null;
        // 交换左右子树
        TreeNode tmp = root.left;
        root.left = root.right;
        root.right = tmp;
        invertTree(root.left);
        invertTree(root.right);
        return root;
    }
}

// Hot100 #230 二叉搜索树中第 K 小的元素（中等）· 二叉搜索树
import java.util.*;

class Solution {
    // 思路:中序遍历得到升序序列,取第 k 个元素
    // 关键:显式栈模拟递归,避免递归栈开销
    // 易错:k 递减到 0 立即返回当前节点值
    // 复杂度:时间 O(h + k),空间 O(h),h 为树高
    public int kthSmallest(TreeNode root, int k) {
        Deque<TreeNode> st = new ArrayDeque<>();
        TreeNode cur = root;
        while (cur != null || !st.isEmpty()) {
            while (cur != null) { st.push(cur); cur = cur.left; }
            cur = st.pop();
            if (--k == 0) return cur.val;  // 第 k 个出栈节点即答案
            cur = cur.right;
        }
        return -1;
    }
}

// Hot100 #234 回文链表（简单）· 链表
class Solution {
    public boolean isPalindrome(ListNode head) {
        // ① 算法核心思路：快慢指针找中点，反转后半段，再与前半段逐节点比较值
        // ② 关键步骤与易错点：循环条件 fast != null && fast.next != null；比较以 right 非空为界，奇偶长度均正确
        // ③ 时间复杂度 O(n)，空间复杂度 O(1)
        ListNode slow = head;
        ListNode fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        ListNode prev = null;
        while (slow != null) {
            ListNode nxt = slow.next;
            slow.next = prev;
            prev = slow;
            slow = nxt;
        }
        ListNode left = head;
        ListNode right = prev;
        while (right != null) {
            if (left.val != right.val) return false;
            left = left.next;
            right = right.next;
        }
        return true;
    }
}

