class Solution {
    // 思路:后序遍历查找 p 与 q,汇聚点即最近公共祖先
    // 关键:左右子树都非空时返回当前节点
    // 易错:目标节点本身就是祖先,命中即返回
    // 复杂度:时间 O(n),空间 O(h),h 为树高
    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        return lca(root, p, q);
    }
    TreeNode lca(TreeNode node, TreeNode p, TreeNode q) {
        if (node == null || node == p || node == q) return node;
        TreeNode l = lca(node.left, p, q);
        TreeNode r = lca(node.right, p, q);
        if (l != null && r != null) return node;  // 两侧都命中目标,当前节点是最近公共祖先
        return l != null ? l : r;
    }
}

// Hot100 #238 除自身以外数组的乘积（中等）· 前缀积
class Solution {
    public int[] productExceptSelf(int[] nums) {
        // 核心思路：两趟扫描——先从左到右累乘前缀积，再从右到左累乘后缀积，
        // res[i] 最终为除 nums[i] 外所有元素的乘积，全程不使用除法。
        // 关键步骤：前缀趟先赋值再累乘，后缀趟先累乘再乘入结果；
        // 不依赖除法，因此输入含 0 时同样正确。
        // 复杂度：时间 O(n)，空间 O(1)（不计返回数组）。
        int n = nums.length;
        int[] res = new int[n];
        int prefix = 1;
        for (int i = 0; i < n; i++) { res[i] = prefix; prefix *= nums[i]; }
        int suffix = 1;
        for (int i = n - 1; i >= 0; i--) { res[i] *= suffix; suffix *= nums[i]; }
        return res;
    }
}

