// Hot100 #287 寻找重复数（中等）· 快慢指针/二分
class Solution {
    // 算法思路：把数组看作链表，下标 i 指向 nums[i]，重复元素导致环的出现
    // 快慢指针先在环中相遇，再让慢指针从头出发，两指针同速走到环入口
    // 环入口下标就是重复数字，时间复杂度 O(n)，空间复杂度 O(1)
    public int findDuplicate(int[] nums) {
        int slow = 0, fast = 0;
        while (true) {
            slow = nums[slow];
            fast = nums[nums[fast]];
            if (slow == fast) break;
        }
        slow = 0;
        while (slow != fast) {
            slow = nums[slow];
            fast = nums[fast];
        }
        return slow;
    }
}

// Hot100 #295 数据流的中位数（困难）· 堆/设计
import java.util.*;

class MedianFinder {
    PriorityQueue<Integer> lo = new PriorityQueue<>(Collections.reverseOrder()); // 大顶堆
    PriorityQueue<Integer> hi = new PriorityQueue<>(); // 小顶堆
    public MedianFinder() {}
    public void addNum(int num) {
        lo.add(num);
        hi.add(lo.poll());
        if (hi.size() > lo.size()) lo.add(hi.poll());
    }
    public double findMedian() {
        if (lo.size() > hi.size()) return lo.peek();
        return (lo.peek() + hi.peek()) / 2.0;
    }
}

// Hot100 #300 最长递增子序列（中等）· 动态规划/二分

class Solution {
    public int lengthOfLIS(int[] nums) {
        // 算法思路：贪心加二分。tails[i] 记录长度为 i+1 的递增子序列的最小末尾值，
        // tails 保持严格单调递增，可用二分定位。
        // 关键点：用 x 覆盖第一个不小于 x 的位置，使末尾值尽量小；
        // 找不到则追加到尾部，此时最长长度加一。
        // 时间复杂度 O(n log n)，空间复杂度 O(n)。
        int[] tails = new int[nums.length];
        int len = 0;
        for (int x : nums) {
            int lo = 0, hi = len; // 在 [lo, hi) 中找第一个 >= x 的位置
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (tails[mid] < x) lo = mid + 1;
                else hi = mid;
            }
            tails[lo] = x;
            if (lo == len) len++;
        }
        return len;
    }
}

// Hot100 #322 零钱兑换（中等）· 动态规划
import java.util.*;

class Solution {
    public int coinChange(int[] coins, int amount) {
        // 算法思路：完全背包动态规划。dp[i] 表示凑成金额 i 所需的最少硬币数，
        // 转移方程 dp[i] = min(dp[i - c] + 1)，硬币可重复使用。
        // 关键点：dp[0] 初始化为 0，其余初始化为 INF 表示不可达；
        // 返回前判断 dp[amount] 是否仍为 INF，是则返回 -1。
        // 时间复杂度 O(amount * 硬币种类数)，空间复杂度 O(amount)。
        int INF = Integer.MAX_VALUE / 2;
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 1; i <= amount; i++) {
            for (int c : coins) {
                if (c <= i) dp[i] = Math.min(dp[i], dp[i - c] + 1);
            }
        }
        return dp[amount] >= INF ? -1 : dp[amount];
    }
}

// Hot100 #347 前 K 个高频元素（中等）· 堆/哈希
import java.util.*;

class Solution {
    // 算法思路: 哈希表统计频率, 按频率降序、数值升序排序后取前 k 个。
    // 关键点: 比较器先比频率再比数值, 保证输出顺序确定。
    // 时间复杂度 O(n log n), 空间复杂度 O(n)。
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int x : nums) cnt.put(x, cnt.getOrDefault(x, 0) + 1);
        List<Map.Entry<Integer, Integer>> items = new ArrayList<>(cnt.entrySet());
        // 按 (-频率, 数值) 排序，保证确定性顺序
        items.sort((a, b) -> {
            int cf = Integer.compare(b.getValue(), a.getValue());
            return cf != 0 ? cf : Integer.compare(a.getKey(), b.getKey());
        });
        int[] ans = new int[k];
        for (int i = 0; i < k; i++) ans[i] = items.get(i).getKey();
        return ans;
    }
}

// Hot100 #394 字符串解码（中等）· 栈
import java.util.*;

class Solution {
    // 算法思路: 栈模拟解码。遇到 [ 把当前字符串与重复次数压栈, 遇到 ] 弹出并按次数拼接。
    // 关键点: 数字可能多位需累加; 嵌套结构靠栈的先进后出还原。
    // 时间复杂度 O(解码后字符串长度), 空间复杂度 O(解码后字符串长度)。
    public String decodeString(String s) {
        Deque<String> strStack = new ArrayDeque<>();   // 存之前的字符串
        Deque<Integer> numStack = new ArrayDeque<>();  // 存重复次数
        StringBuilder cur = new StringBuilder();
        int num = 0;
        for (char ch : s.toCharArray()) {
            if (ch >= '0' && ch <= '9') {
                num = num * 10 + (ch - '0');            // 数字可能多位
            } else if (ch == '[') {
                strStack.push(cur.toString());
                numStack.push(num);
                cur.setLength(0);
                num = 0;
            } else if (ch == ']') {
                String pre = strStack.pop();
                int cnt = numStack.pop();
                String tmp = cur.toString();
                for (int i = 1; i < cnt; i++) cur.append(tmp);
                cur.insert(0, pre);
            } else {
                cur.append(ch);
            }
        }
        return cur.toString();
    }
}

// Hot100 #416 分割等和子集（中等）· 动态规划/背包

class Solution {
    public boolean canPartition(int[] nums) {
        // 算法思路：等价于 0/1 背包。若能选出若干数凑成总和的一半 target，
        // 则剩余数自然构成另一半，即可等和分割。
        // 关键点：总和为奇数直接返回 false；内层循环倒序遍历保证每个数只用一次。
        // 易错点：总和用 long 累加防止溢出，target 再转回 int。
        // 时间复杂度 O(n * target)，空间复杂度 O(target)。
        long total = 0;
        for (int v : nums) total += v;
        if (total % 2 == 1) return false;
        int target = (int) (total / 2);
        boolean[] dp = new boolean[target + 1];
        dp[0] = true;
        for (int v : nums) {
            for (int s = target; s >= v; s--) {
                if (dp[s - v]) dp[s] = true;
            }
        }
        return dp[target];
    }
}

// Hot100 #437 路径总和 III（中等）· 二叉树/前缀和
import java.util.*;

class Solution {
    // 思路:前缀和哈希,统计根到当前节点的路径中和为 target 的数量
    // 关键:pre 记录前缀和出现次数,累加 pre[cur - target]
    // 易错:回溯时 pre[cur] 自减;用 long 防溢出
    // 复杂度:时间 O(n),空间 O(h),h 为树高
    Map<Long, Integer> pre = new HashMap<>();
    int targetSum;
    int ans;

    public int pathSum(TreeNode root, int targetSum) {
        pre.clear();
        pre.put(0L, 1);
        ans = 0;
        this.targetSum = targetSum;
        dfs(root, 0L);
        return ans;
    }
    void dfs(TreeNode node, long cur) {
        if (node == null) return;
        cur += node.val;
        ans += pre.getOrDefault(cur - targetSum, 0);  // 累加以当前节点为终点的合法路径数
        pre.put(cur, pre.getOrDefault(cur, 0) + 1);
        dfs(node.left, cur);
        dfs(node.right, cur);
        pre.put(cur, pre.get(cur) - 1);
    }
}

// Hot100 #438 找到字符串中所有字母异位词（中等）· 滑动窗口
import java.util.*;

class Solution {
    public List<Integer> findAnagrams(String s, String p) {
        // 核心思路：定长滑动窗口加 26 长度计数数组
        // need 为 p 的字符频次，win 为窗口内的字符频次
        // 窗口右端进一个字符、左端出一个字符，保持长度不变
        // 频次完全相等时记录窗口起点下标
        // 时间复杂度 O(n)，空间复杂度 O(1)
        List<Integer> res = new ArrayList<>();
        if (s.length() < p.length()) return res;
        int[] need = new int[26];
        int[] win = new int[26];
        for (int i = 0; i < p.length(); i++) need[p.charAt(i) - 'a']++;
        int m = p.length();
        for (int i = 0; i < s.length(); i++) {
            win[s.charAt(i) - 'a']++;
            if (i >= m) win[s.charAt(i - m) - 'a']--;
            if (i >= m - 1 && Arrays.equals(win, need)) res.add(i - m + 1);
        }
        return res;
    }
}

// Hot100 #543 二叉树的直径（简单）· 二叉树/DFS
class Solution {
    private int best = 0;

    // 思路：后序遍历求每个节点的左右子树深度，经过该节点的最长路径为左深加右深。
    // 关键点：用全局变量 best 记录所有节点路径的最大值，直径不一定经过根节点。
    // 易错点：函数返回的是子树最大深度，路径长度只用于更新 best。
    // 复杂度：时间 O(n)，空间 O(h)，h 为树高（递归栈深度）。
    public int diameterOfBinaryTree(TreeNode root) {
        depth(root);
        return best;
    }

    private int depth(TreeNode node) {
        if (node == null) return 0;
        int l = depth(node.left);
        int r = depth(node.right);
        best = Math.max(best, l + r);  // 经过当前节点的最长路径
        return 1 + Math.max(l, r);
    }
}

// Hot100 #560 和为 K 的子数组（中等）· 前缀和/哈希
import java.util.*;

class Solution {
    public int subarraySum(int[] nums, int k) {
        // 核心思路：前缀和加哈希表统计出现次数
        // 子数组和为 k 当且仅当 pre - k 在前面出现过
        // 先累加答案再更新当前前缀和计数
        // 用 long 存储前缀和防止溢出
        // 时间复杂度 O(n)，空间复杂度 O(n)
        Map<Long, Integer> cnt = new HashMap<>();
        cnt.put(0L, 1);
        long pre = 0;
        int ans = 0;
        for (int x : nums) {
            pre += x;
            ans += cnt.getOrDefault(pre - k, 0);
            cnt.put(pre, cnt.getOrDefault(pre, 0) + 1);
        }
        return ans;
    }
}

// Hot100 #739 每日温度（中等）· 单调栈
import java.util.*;

class Solution {
    // 算法思路: 单调栈。从右向左遍历, 栈存下标且温度严格递减。
    // 关键点: 弹出所有不大于当前温度的下标, 栈顶即右侧第一个更高温度的位置。
    // 时间复杂度 O(n), 空间复杂度 O(n)。
    public int[] dailyTemperatures(int[] temperatures) {
        int n = temperatures.length;
        int[] ans = new int[n];
        Deque<Integer> st = new ArrayDeque<>();   // 单调递减栈，存下标
        for (int i = n - 1; i >= 0; i--) {
            while (!st.isEmpty() && temperatures[st.peek()] <= temperatures[i]) st.pop();
            if (!st.isEmpty()) ans[i] = st.peek() - i;
            st.push(i);
        }
        return ans;
    }
}

// Hot100 #763 划分字母区间（中等）· 贪心
import java.util.*;

class Solution {
    // 算法思路: 贪心。last 记录每个字母最后一次出现的下标, 扫描时扩展当前段右边界。
    // 关键点: i 到达 end 时切割一段, 记录长度后重置起点。
    // 时间复杂度 O(n), 空间复杂度 O(1) (字符集固定为 26)。
    public List<Integer> partitionLabels(String s) {
        int[] last = new int[26];
        for (int i = 0; i < s.length(); i++) last[s.charAt(i) - 'a'] = i;
        List<Integer> list = new ArrayList<>();
        int start = 0, end = 0;
        for (int i = 0; i < s.length(); i++) {
            end = Math.max(end, last[s.charAt(i) - 'a']);
            if (i == end) {
                list.add(end - start + 1);
                start = i + 1;
            }
        }
        return list;
    }
}

// Hot100 #994 腐烂的橘子（中等）· 图/BFS
import java.util.*;

class Solution {
    public int orangesRotting(int[][] grid) {
        // 核心思路: 多源 BFS，所有烂橘子同时向外扩散，扩散层数即所需分钟数。
        // 关键步骤: 初始把全部烂橘子入队并统计新鲜橘子数，逐层感染并计时。
        // 易错点: 结束时仍有新鲜橘子说明无法全部感染，返回 -1。
        // 复杂度: 每个格子入队一次，时间 O(m·n)，空间 O(m·n)。
        int m = grid.length, n = grid[0].length;
        Queue<int[]> q = new LinkedList<>();
        int fresh = 0;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 2) q.offer(new int[]{i, j});
                else if (grid[i][j] == 1) fresh++;
            }
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        int minutes = 0;
        while (!q.isEmpty() && fresh > 0) {
            int sz = q.size();
            for (int k = 0; k < sz; k++) {
                int[] cur = q.poll();
                for (int[] d : dirs) {
                    int ni = cur[0] + d[0], nj = cur[1] + d[1];
                    if (ni >= 0 && ni < m && nj >= 0 && nj < n && grid[ni][nj] == 1) {
                        grid[ni][nj] = 2;
                        fresh--;
                        q.offer(new int[]{ni, nj});
                    }
                }
            }
            minutes++;
        }
        return fresh > 0 ? -1 : minutes;
    }
}

// Hot100 #1143 最长公共子序列（中等）· 动态规划
class Solution {
    // 算法思路：动态规划，dp[i][j] 表示 text1 前 i 个字符与 text2 前 j 个字符的最长公共子序列长度
    // 字符相等则 dp[i][j] = dp[i-1][j-1] + 1，否则取上方与左方的较大值
    // 易错点：下标错位，text1[i-1] 对应第 i 个字符，dp 多开一行一列
    // 时间复杂度 O(m*n)，空间复杂度 O(m*n)
    public int longestCommonSubsequence(String text1, String text2) {
        int m = text1.length(), n = text2.length();
        int[][] dp = new int[m + 1][n + 1];
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (text1.charAt(i - 1) == text2.charAt(j - 1)) dp[i][j] = dp[i - 1][j - 1] + 1;
                else dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
        return dp[m][n];
    }
}
